package com.bank.denorm.model;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private long txnCount;                 // DENORMALIZED counter
    private BigDecimal monthlyTotal;       // DENORMALIZED sum

    public Account(String accountId, String holderName, BigDecimal balance) {
            this.accountId = accountId;
            this.holderName = holderName;
            this.balance = balance;
            this.txnCount = 0
            this.monthlyTotal = BigDecimal.ZERO;
    }
    public void debit(BigDecimal amt)  { balance = balance.subtract(amt); }
    public void credit(BigDecimal amt) { balance = balance.add(amt); }
    public void recordTxn(BigDecimal amt) { txnCount++; monthlyTotal = monthlyTotal.add(amt); }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public long getTxnCount() { return txnCount; }
    public BigDecimal getMonthlyTotal() { return monthlyTotal; }
}
