package com.bank.denorm.service;

import com.bank.denorm.model.Account;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // One atomic unit: move money AND update denormalized counters together.
    public void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        from.recordTxn(amount);   // counter kept consistent in the same step
        log.info(() -> "Transfer Rs." + amount + " " + from.getAccountId()
                + "→" + to.getAccountId() + " | count now " + from.getTxnCount());
    }
}
