package com.bank.denorm.service;

import com.bank.denorm.model.Account;
import java.util.logging.Logger;

public class DashboardService {
    private static final Logger log = Logger.getLogger(DashboardService.class.getName());

    // Pure read: no COUNT, no SUM — just read the pre-computed fields.
    public String render(Account a) {
        return "Dashboard[" + a.getHolderName() + "] balance=Rs." + a.getBalance()
                + " txns=" + a.getTxnCount() + " monthlyTotal=Rs." + a.getMonthlyTotal();
    }
}
