package com.bank.denorm;

import com.bank.denorm.model.Account;
import com.bank.denorm.service.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class DenormDemo {
    private static final Logger log = Logger.getLogger(DenormDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        Account rajesh = new Account("SAV2001","Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001","Priya Sharma", new BigDecimal("250000"));
        TransferService transfers = new TransferService();
        DashboardService dash = new DashboardService();

        transfers.transfer(rajesh, priya, new BigDecimal("50000"));
        transfers.transfer(rajesh, priya, new BigDecimal("25000"));
        log.info(dash.render(rajesh));   // instant read, no aggregation
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
